INSERT INTO `products` (`id`, `cat_id`, `sub_cat_id`, `collection_id`, `name`, `style_no`, `position`, `position_collection`, `image`, `short_desc`, `desc`, `price`, `offer_price`, `size_chart`, `pack`, `master_pack`, `size_chart_image`, `only_for`, `slug`, `meta_title`, `meta_desc`, `meta_keyword`, `view_count`, `last_view_count_updated_at`, `is_trending`, `is_best_seller`, `status`, `created_at`, `updated_at`) VALUES(191, 11, 0, 15, 'Ultra-Soft Premium Combed Cotton Solid Trunk', 'UK 44', 1, 1, 'public/uploads/product/updated-images/uk-44/uk-44-1641731587-1680354990.jpg', '<h4><strong>Product Feature:</strong></h4><figure class=\"table\"><table><tbody><tr><td>Crafted from 100% Premium Combed cotton.</td></tr><tr><td>Feather-touch ultra-soft waistband that leaves no marks.</td></tr><tr><td>Super moisture absorbent fabric for unmatched breathability.</td></tr><tr><td>Tag-free for itch-free comfort.&nbsp;</td></tr><tr><td>&nbsp;</td></tr></tbody></table></figure><p>&nbsp;</p>', '', 260.00, 260.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/uk-44/uk-44-163811532-1680251401.jpg', 'all', 'ultra-soft-premium-combed-cotton-solid-trunk', NULL, NULL, NULL, 4695, '2026-01-20 17:01:20', 1, 0, 1, '2023-03-31 17:59:08', '2026-01-20 17:01:20'),(192, 9, 0, 4, 'STRIPE ROUND NECK T-SHIRT', 'OA 424', 1, 1, 'public/uploads/product/1682670777.1.jpg', '<p>Premium combed cotton rich fabric , Modern fit for extra comfort , Twill tape reinforcement on neck for enhanced style and durability , To be worn as loungewear or casual tee , Available in attractive colors</p>', '', 449.00, 449.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/oa-424/oa-424-1280253009-1700740510.jpg', 'all', 'stripe-round-neck-t-shirt', NULL, NULL, NULL, 3087, '2025-06-20 21:18:27', 0, 0, 0, '2023-04-28 18:02:57', '2025-06-20 21:49:17'),(193, 9, 0, 17, 'ONN Men\'s Half Sleeve Polo Neck Fashion T-Shirt with Pocket', 'OA 1129', 1, 1, 'public/uploads/product/1682679048.1.jpg', '<p>Made from a perfect blend of cotton rich fabric , Modern yet relaxed fit for all day comfort , Fashion and casual wear , Available in attractive colours , Soft collar rib for neck comfort , Elegant look and easy care</p>', '', 649.00, 649.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/oa-1129/oa-1129-1617519941-1700740725.jpg', 'all', 'onn-mens-half-sleeve-polo-neck-fashion-t-shirt-with-pocket-oa-1129', NULL, NULL, NULL, 2729, '2026-01-20 23:28:41', 1, 0, 1, '2023-04-28 20:20:48', '2026-01-20 23:28:41'),(194, 9, 0, 17, 'ONN Men\'s Half Sleeve Polo Fashion T-Shirt with Pocket', 'OA 1128', 1, 1, 'public/uploads/product/1685959255.1.jpg', '<p>The ONN Men\'s Perfect Blend Polo T-Shirt is designed for comfort and style, crafted from a cotton-rich fabric that feels soft and gentle on the skin. Its half-sleeve design offers a perfect balance of practicality and fashion, making it ideal for a variety of occasions. Available in a range of solid colors, this polo t-shirt allows you to express your personal style effortlessly. The classic polo collar with a button placket adds a sophisticated touch, elevating its overall appeal. Whether you\'re dressing casually for an outing or attending a semi-formal event, this versatile piece can be paired with jeans, chinos, or shorts for a polished look.</p>', '', 649.00, 649.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/oa-1128/oa-1128-651604195-1700740827.jpg', 'all', 'onn-mens-half-sleeve-polo-fashion-t-shirt-with-pocket-oa-1128', NULL, NULL, NULL, 3482, '2026-01-21 01:17:58', 1, 0, 1, '2023-06-05 19:30:55', '2026-01-21 01:17:58'),(195, 9, 0, 4, 'Auto Stripe Polo T-Shirt', 'OA 436', 1, 1, 'public/uploads/product/updated-images/oa-436/oa-436-809612218-1707287634.jpg', '<p>Stylish design with comfortable half sleeves, making it suitable for warmer weather or casual occasions. The T-shirt showcases an eye-catching auto striped pattern, adding a touch of sophistication and modernity to your outfit. Crafted from a high-quality cotton blend, this polo T-shirt offers a soft and breathable feel against the skin, ensuring maximum comfort throughout the day.</p>', '', 699.00, 699.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/oa-436/oa-436-1205571778-1707287634.jpg', 'all', 'auto-stripe-polo-t-shirt', NULL, NULL, NULL, 3863, '2025-04-03 23:40:06', 1, 0, 0, '2023-06-22 18:42:32', '2025-04-03 23:40:31'),(196, 9, 0, 4, 'Printed Polo T-Shirt', 'OA 434', 1, 1, 'public/uploads/product/1687774169.1.jpg', '<p>Premium combed cotton rich fabric , Modern fit for extra comfort. To be worn as loungewear or casual tee , Available in attractive colors</p>', '', 675.00, 675.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/oa-434/oa-434-1226014099-1687774201.jpg', 'all', 'printed-polo-t-shirt', NULL, NULL, NULL, 4447, '2026-01-20 23:32:14', 0, 0, 1, '2023-06-26 19:39:29', '2026-01-20 23:32:14'),(198, 20, 0, 16, 'Anthemison 15\" Laptop Briefcase', 'Anthemison', 1, 1, 'public/uploads/product/1691667940.1.jpg', '<ul><li>Stylish Design: The briefcase bag features a sleek and stylish design that adds a touch of professionalism to your daily look.</li><li>15 inch Laptop Compatibility: Designed to comfortably accommodate up to a 15-inch laptop, providing a secure and padded compartment to keep your device safe during travel or daily commutes.</li><li>Premium PU Leather: Constructed from high-quality PU leather, the bag offers a durable and sophisticated outer material that is both stylish and resilient.</li><li>Lightweight Build: The bag is crafted to be lightweight, making it easy to carry around without adding unnecessary weight to your load.</li><li>Comfortable Handles: Equipped with comfortable handles that make it convenient to carry the bag by hand.</li></ul>', '', 2299.00, 2299.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/anthemison/anthemison-1553026743-1700742809.jpg', 'all', 'anthemison-15-laptop-briefcase', NULL, NULL, NULL, 1782, '2026-01-20 23:38:25', 0, 0, 1, '2023-08-10 21:15:40', '2026-01-20 23:38:25'),(199, 20, 0, 16, 'Croco Classy Onn 15\" Laptop Briefcase', 'Croco Classy Onn', 1, 1, 'public/uploads/product/updated-images/croco-classy-onn/croco-classy-onn-1986214608-1692793612.JPG', '<ul><li>Stylish and Professional: The ONN Croco Classy PU Leather 15 Inch Briefcase for Men exudes an air of sophistication, making it a perfect accessory for professionals who value both functionality and style.</li><li>Premium PU Leather: Crafted from high-quality PU leather with a crocodile-patterned texture, this briefcase offers a luxurious look and feel while being durable and easy to maintain.</li><li>Optimal Laptop Protection: Designed to accommodate up to a 15-inch laptop, the briefcase features a padded compartment that safeguards your device from impacts and scratches, ensuring your valuable electronics are well-protected during your travels.</li><li>Spacious Interior: With a well-organized and roomy interior, this briefcase provides ample space for your essentials, including documents, notebooks, pens, chargers, and more. The thoughtful layout helps you stay organized and efficient.</li><li>Professional Appeal: Whether you\'re headed to the office, a business meeting, or a formal event, the sleek design and subtle branding of this briefcase enhance your professional image and complement your attire.</li></ul>', '', 2399.00, 2399.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/croco-classy-onn/croco-classy-onn-1838184522-1700742849.jpg', 'all', 'croco-classy-onn-15-laptop-briefcase', NULL, NULL, NULL, 2211, '2026-01-20 23:38:41', 0, 0, 1, '2023-08-10 21:29:10', '2026-01-20 23:38:41'),(202, 21, 0, 16, 'Hinged Cross Body', 'Hinged Cross Body', 1, 1, 'public/uploads/product/updated-images/hinged-cross-body/hinged-cross-body-71302944-1692792244.jpg', '<ul><li>Stylish and Functional: The ONN Men\'s PU Leather Messenger Bag combines fashion with practicality, making it an ideal accessory for the modern man.</li><li>Premium PU Leather: Crafted from high-quality PU leather, this bag exudes a sophisticated look while being durable and easy to maintain.</li><li>Compact Size: Designed for convenience, its compact dimensions make it perfect for carrying essentials without feeling bulky.</li><li>Crossbody Comfort: The adjustable crossbody strap ensures a comfortable fit and allows for hands-free carrying, whether you\'re commuting or traveling.</li><li>Ample Storage: Despite its small size, the bag offers ample storage with multiple compartments including a main compartment and exterior pockets.</li></ul>', '', 1499.00, 1499.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/hinged-cross-body/hinged-cross-body-1829174946-1700742960.jpg', 'all', 'hinged-cross-body', NULL, NULL, NULL, 1948, '2026-01-20 23:35:46', 0, 0, 1, '2023-08-10 21:36:54', '2026-01-20 23:35:46'),(205, 21, 0, 16, 'Lestrad Cross Body', 'Lestrad Cross Body', 1, 1, 'public/uploads/product/updated-images/lestrad-cross-body/lestrad-cross-body-1371032082-1692796319.JPG', '<ul><li>Stylish and Practical : The ONN PU Leather Small Messenger Bag is designed for men who value both style and functionality, making it an ideal accessory for various occasions.</li><li>Crossbody Convenience : The adjustable crossbody strap ensures comfortable wear and allows you to keep your hands free while on the move.</li><li>Crossbody Convenience : The adjustable crossbody strap ensures comfortable wear and allows you to keep your hands free while on the move.</li><li>Versatile Use : Ideal for work, business meetings, or casual outings, this messenger bag complements your attire and keeps your essentials close at hand.</li><li>Secure and Accessible : The secure zipper closure keeps your belongings safe, while the strategically placed compartments and pockets provide easy access to frequently used items.</li></ul>', '', 1499.00, 1499.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/lestrad-cross-body/lestrad-cross-body-1013125139-1700742998.jpg', 'all', 'lestrad-cross-body', NULL, NULL, NULL, 2029, '2026-01-20 23:35:13', 0, 0, 1, '2023-08-10 21:44:04', '2026-01-20 23:35:13'),(208, 22, 0, 16, 'Black Lazor Backpack', 'PLONP305113-1', 1, 1, 'public/uploads/product/updated-images/plonp305113-1/plonp305113-1-1819691796-1691670286.jpg', '<p>Black Lazor Backpack</p>', '', 2499.00, 2499.00, NULL, '1 PC', NULL, NULL, 'all', 'black-lazor-backpack', NULL, NULL, NULL, 2347, '2026-01-20 23:32:46', 0, 0, 1, '2023-08-10 21:52:33', '2026-01-20 23:32:46'),(209, 19, 0, 16, 'Black Nedra Duffle Bag', 'PLONP275251-1', 1, 1, 'public/uploads/product/updated-images/plonp275251-1/plonp275251-1-1525946556-1700742491.jpg', '<p>Black Nedra Duffle Bag</p>', '', 2449.00, 2449.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/plonp275251-1/plonp275251-1-1633708975-1700742499.jpg', 'all', 'black-nedra-duffle-bag', NULL, NULL, NULL, 1198, '2026-01-20 23:36:18', 0, 0, 1, '2023-08-10 21:56:52', '2026-01-20 23:36:18'),(210, 19, 0, 16, 'Tan Pledar Duffle Bag', 'PLONP265065-12', 1, 1, 'public/uploads/product/1691670571.1.jpg', '<p>Tan Pledar Duffle Bag</p>', '', 2449.00, 2449.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/plonp265065-12/plonp265065-12-1383829636-1700742648.jpg', 'all', 'tan-pledar-duffle-bag', NULL, NULL, NULL, 1633, '2026-01-20 23:37:05', 0, 0, 1, '2023-08-10 21:59:31', '2026-01-20 23:37:05'),(211, 19, 0, 16, 'Drefy Duffle Bag', 'Drefy', 1, 1, 'public/uploads/product/updated-images/drefy/drefy-325991933-1692795655.JPG', '<ul><li>Stylish and Durable: Made from high-quality PU leather, this duffle bag boasts a stylish appearance while being tough enough to withstand travel demands.</li><li>Spacious Interior: The weekender bag offers ample space to pack your essentials, making it suitable for short trips or as a gym duffle bag.</li><li>Compact Design: Despite its roomy interior, the bag maintains a compact and manageable size, making it convenient for carrying and storing.</li><li>Comfortable to Carry: Equipped with comfortable handles, a detachable shoulder strap, or even a crossbody option, ensuring different carrying preferences are accommodated.</li><li>Versatile Use: Ideal for various occasions - from travel and weekend getaways to gym sessions and more, providing versatility in its usage.</li></ul>', '', 2349.00, 2349.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/drefy/drefy-19686734-1700742714.jpg', 'all', 'drefy-duffle-bag', NULL, NULL, NULL, 1411, '2026-01-20 23:34:23', 0, 0, 1, '2023-08-10 22:03:47', '2026-01-20 23:34:23'),(215, 9, 0, 15, 'EMBOSS ROUND NECK T-SHIRT', 'UK 55', 1, 1, 'public/uploads/product/1692621288.1.jpg', '<ul><li>Made from 100% Premium Combed Cotton.</li><li>Ribbed crew neck prevents sagging.</li><li>Stylized emboss print for quirky look.</li><li>A wardrobe staple for effortless style.&nbsp;</li><li>Perfect as casual wear and loungewear.&nbsp;</li></ul>', '', 475.00, 475.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/uk-55/uk-55-1900904983-1692621305.jpg', 'all', 'emboss-round-neck-t-shirt', NULL, NULL, NULL, 2652, '2026-01-20 17:09:41', 0, 0, 1, '2023-08-21 22:04:48', '2026-01-20 17:09:41'),(216, 5, 0, 15, 'TANK TOP', 'UK 25', 1, 1, 'public/uploads/product/1692623289.1.jpg', '<ul><li>Made from 100% premium combed cotton.</li><li>Urban design and no itchy tags.</li><li>Scoop neck for easy wearing</li><li>Perfect gym wear and loungewear.</li></ul>', '', 270.00, 270.00, NULL, '1 PC', NULL, 'public/uploads/product/updated-images/uk-25/uk-25-2127549009-1692623301.jpg', 'all', 'tank-top', NULL, NULL, NULL, 4912, '2026-01-20 16:54:40', 0, 0, 1, '2023-08-21 22:38:09', '2026-01-20 16:54:40'),(218, 14, 0, 2, 'NO SHOW SOCKS', 'OF 3003 D', 1, 1, 'public/uploads/product/1693572740.1.jpg', '<p>Elastane body for maximum comfort and stretch , Elastane welt for a no-sag grip , Ultra soft cotton for smooth feel ,Endure freshness</p>', '', 105.00, 105.00, NULL, '1 PC PACK', NU